//! R4 share-reader parity: replays `tests/spec/share/cases.json` — the real TypeScript
//! readers' answers over a scripted virtual share — against the Rust readers, byte for byte
//! (`js_text` writes numbers and key order as JavaScript does). The corpus is generated by
//! `bun tests/spec/share-read-parity.ts --regenerate`; the status-documents expectations are
//! filled on the build host, where the aac-status native module the TS wrapper calls exists.

use aac_status::share::catalog::{self, CatalogReader};
use aac_status::share::quota::{self, QuotaReportReader};
use aac_status::share::registry::PmMailRegistryReader;
use aac_status::share::reports::{self, AgentReportsReader, Limits};
use aac_status::share::status_docs::{self, StatusDocsReader};
use aac_status::share::{js_text, Dirent, ReadError, ShareFs};
use aac_files::read::Stat;
use serde::Deserialize;
use serde_json::{json, Value as Json};
use std::io;
use std::path::{Path, PathBuf};

#[derive(Clone, Deserialize)]
struct Node {
    #[serde(rename = "type")]
    kind: String,
    #[serde(default)]
    content: Option<String>,
    #[serde(default)]
    mtime: Option<f64>,
    #[serde(default)]
    ino: Option<u64>,
    #[serde(default)]
    ctime: Option<f64>,
    #[serde(default)]
    size: Option<u64>,
    #[serde(default)]
    target: Option<String>,
}

#[derive(Deserialize)]
struct StepLimits {
    writers: Option<usize>,
    cards: Option<usize>,
    bytes: Option<u64>,
}

#[derive(Deserialize)]
struct DocsLimits {
    writers: Option<usize>,
    retained: Option<usize>,
}

#[derive(Deserialize)]
struct Expect {
    reports: String,
    #[serde(rename = "reportsChanged")]
    reports_changed: bool,
    quota: String,
    #[serde(rename = "quotaChanged")]
    quota_changed: bool,
    registry: Json,
    docs: Option<String>,
    #[serde(rename = "docsChanged")]
    docs_changed: Option<bool>,
    catalog: String,
}

#[derive(Deserialize)]
struct Step {
    name: String,
    now: u64,
    tree: Vec<(String, Node)>,
    errors: Json,
    limits: Option<StepLimits>,
    #[serde(rename = "docsLimits")]
    docs_limits: Option<DocsLimits>,
    expect: Expect,
}

#[derive(Deserialize)]
struct Corpus {
    root: String,
    #[serde(rename = "registryDir")]
    registry_dir: String,
    steps: Vec<Step>,
}

/// The scripted share: one image per step, listing in the corpus's own order, errors by path.
struct MemFs {
    tree: indexmap::IndexMap<String, Node>,
    errors: Json,
}

fn injected(errors: &Json, path: &str, op: &str) -> Option<io::Error> {
    let code = errors.get(path)?.get(op)?.as_str()?;
    Some(match code {
        "ENOENT" => io::Error::from_raw_os_error(2),
        "ENOTDIR" => io::Error::from_raw_os_error(20),
        "ESTALE" => io::Error::from_raw_os_error(116),
        "EACCES" => io::Error::from_raw_os_error(13),
        other => io::Error::new(io::ErrorKind::Other, other.to_string()),
    })
}

impl MemFs {
    fn node(&self, path: &str) -> Option<&Node> {
        self.tree.get(path)
    }

    fn resolve(&self, path: &str) -> Option<&Node> {
        let node = self.node(path)?;
        if node.kind == "link" {
            return self.resolve(node.target.as_deref()?);
        }
        Some(node)
    }
}

impl ShareFs for MemFs {
    fn list(&self, dir: &Path) -> io::Result<Vec<Dirent>> {
        let dir = dir.to_string_lossy().replace('\\', "/");
        if let Some(error) = injected(&self.errors, &dir, "list") {
            return Err(error);
        }
        let node = self.node(&dir).ok_or_else(|| io::Error::from_raw_os_error(2))?;
        if node.kind != "dir" {
            return Err(io::Error::from_raw_os_error(20));
        }
        let prefix = format!("{dir}/");
        let mut out = Vec::new();
        for (key, node) in &self.tree {
            let Some(rest) = key.strip_prefix(&prefix) else {
                continue;
            };
            if rest.contains('/') {
                continue;
            }
            out.push(Dirent {
                name: rest.to_string(),
                is_dir: node.kind == "dir",
                is_file: node.kind == "file",
            });
        }
        Ok(out)
    }

    fn stat(&self, file: &Path) -> io::Result<Stat> {
        let file = file.to_string_lossy().replace('\\', "/");
        if let Some(error) = injected(&self.errors, &file, "stat") {
            return Err(error);
        }
        let node = self.resolve(&file).ok_or_else(|| io::Error::from_raw_os_error(2))?;
        Ok(Stat {
            size: node
                .size
                .unwrap_or_else(|| node.content.as_deref().unwrap_or_default().len() as u64),
            mtime_ms: node.mtime.unwrap_or(0.0),
            ctime_ms: node.ctime.or(node.mtime).unwrap_or(0.0),
            device: 1,
            inode: node.ino.unwrap_or(0),
            file: node.kind == "file",
            dir: node.kind == "dir",
        })
    }

    fn read(&self, file: &Path, cap: usize) -> Result<Vec<u8>, ReadError> {
        let file = file.to_string_lossy().replace('\\', "/");
        if let Some(error) = injected(&self.errors, &file, "read") {
            return Err(ReadError::Io(error));
        }
        let node = self.node(&file).ok_or_else(|| ReadError::Io(io::Error::from_raw_os_error(2)))?;
        match node.kind.as_str() {
            "file" => {
                let bytes = node.content.as_deref().unwrap_or_default().as_bytes();
                Ok(bytes[..bytes.len().min(cap + 1)].to_vec())
            }
            // The hardened open refuses a link; a FIFO or folder is not a regular file.
            "link" => Err(ReadError::Io(io::Error::new(io::ErrorKind::Other, "ELOOP"))),
            _ => Err(ReadError::Io(io::Error::new(io::ErrorKind::Other, "ENOTREG"))),
        }
    }
}

fn same(step: &str, member: &str, want: &str, got: String) {
    if want != got {
        let at = want
            .bytes()
            .zip(got.bytes())
            .position(|(a, b)| a != b)
            .unwrap_or(want.len().min(got.len()));
        let from = at.saturating_sub(80);
        panic!(
            "{step}: {member} differs at byte {at}\nwant: ...{}\ngot:  ...{}",
            &want[from..want.len().min(at + 120)],
            &got[from..got.len().min(at + 120)]
        );
    }
}

#[test]
fn the_owned_readers_match_the_typescript_readers_step_for_step() {
    let file = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/spec/share/cases.json");
    let text = std::fs::read_to_string(&file)
        .unwrap_or_else(|error| panic!("the parity corpus is missing ({}): {error}", file.display()));
    let corpus: Corpus = serde_json::from_str(&text).expect("corpus parses");
    let root = PathBuf::from(&corpus.root);
    let regdir = PathBuf::from(&corpus.registry_dir);

    let mut reports = AgentReportsReader::new(root.clone(), Limits::default());
    let mut quota = QuotaReportReader::new(root.clone());
    let mut registry = PmMailRegistryReader::new(regdir);
    let mut docs = StatusDocsReader::new(root.clone(), status_docs::STATUS_DOCS_LIMITS);
    let mut catalog = CatalogReader::new(root.clone());

    for step in &corpus.steps {
        let fs = MemFs {
            tree: step.tree.iter().cloned().collect(),
            errors: step.errors.clone(),
        };
        // The generator keeps one reader across steps, and builds a fresh one for a step
        // that narrows the limits; the replay mirrors that exactly.
        let mut limited_reports;
        let reports_reader = if let Some(limits) = &step.limits {
            let base = Limits::default();
            limited_reports = AgentReportsReader::new(
                root.clone(),
                Limits {
                    writers: limits.writers.unwrap_or(base.writers),
                    cards: limits.cards.unwrap_or(base.cards),
                    bytes: limits.bytes.unwrap_or(base.bytes),
                },
            );
            &mut limited_reports
        } else {
            &mut reports
        };
        let mut limited_docs;
        let docs_reader = if let Some(limits) = &step.docs_limits {
            let base = status_docs::STATUS_DOCS_LIMITS;
            limited_docs = StatusDocsReader::new(
                root.clone(),
                status_docs::Limits {
                    writers: limits.writers.unwrap_or(base.writers),
                    retained: limits.retained.unwrap_or(base.retained),
                },
            );
            &mut limited_docs
        } else {
            &mut docs
        };
        let reports_changed = reports_reader.scan(&fs, step.now);
        let quota_changed = quota.scan(&fs, step.now);
        let docs_changed = docs_reader.scan(&fs, step.now);
        let registry_answer = match registry.scan(&fs, step.now) {
            Ok(scan) => json!({
                "threads": scan.threads,
                "problems": scan.problems.iter().map(|problem| {
                    json!({"item": problem.item, "reason": problem.reason, "since": problem.since})
                }).collect::<Vec<_>>(),
                "changed": scan.changed,
            }),
            Err(message) => json!({"error": message}),
        };
        catalog.scan(&fs, step.now);

        let name = &step.name;
        same(name, "reports", &step.expect.reports, js_text(&reports::state_json(&reports_reader.snapshot())));
        same(name, "quota", &step.expect.quota, js_text(&quota::state_json(&quota.snapshot())));
        assert_eq!(reports_changed, step.expect.reports_changed, "{name}: reports changed flag");
        assert_eq!(quota_changed, step.expect.quota_changed, "{name}: quota changed flag");
        same(name, "registry", &js_text(&step.expect.registry), js_text(&registry_answer));
        same(name, "catalog", &step.expect.catalog, js_text(&catalog::state_json(&catalog.snapshot())));
        if let Some(want) = &step.expect.docs {
            assert_eq!(Some(docs_changed), step.expect.docs_changed, "{name}: docs changed flag");
            same(name, "docs", want, js_text(&status_docs::state_json(&docs_reader.snapshot())));
        }
    }
}
